// Typings for timeline.tsx (projection format 1). Generated by the app from its document schema; do not edit.
// Values must be literals. Unknown attributes are kept as they are (hence the index signatures).

/** Seconds, stored at microsecond precision. */
type Seconds = number;

type Aspect = "16:9" | "4:3" | "3:4" | "9:16" | "1:1" | "4:5";
type TrackKind = "video" | "audio" | "caption" | "adjustment" | "layout";

interface TimelineProps {
  aspect?: Aspect;
  children?: unknown;
}

interface TrackProps {
  /** Track id; omit for a new track. */
  id?: string;
  name?: string;
  kind: TrackKind;
  /** Locked tracks cannot be edited in the GUI. */
  locked?: boolean;
  /** Hidden tracks render nothing. */
  visible?: boolean;
  /** Muted tracks play no audio. */
  muted?: boolean;
  children?: unknown;
  [attribute: string]: unknown;
}

interface ItemBase {
  /** Item id; omit for a new item. */
  id?: string;
  /** Timeline start. */
  start: Seconds;
  /** Timeline end (after start). */
  end: Seconds;
  /** Media name from the header, media id, or a file path (absolute, ./, ../, ~/). */
  src?: string;
  [attribute: string]: unknown;
}

